WITH src AS (SELECT *, TRIM(supplier_name) AS clean_supplier_name FROM suppliers WHERE country IN ('US', 'JP', 'TH') AND city = 'Berlin' AND city <> 'London'), summary AS (SELECT country, CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END AS rating_bucket, ROUND(STDDEV(rating), 2) AS stddev_rating, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(city))) AS city_values FROM src GROUP BY country, CASE WHEN rating >= 3.5 THEN 'high' WHEN rating >= 2.4 THEN 'mid' ELSE 'low' END) SELECT country, rating_bucket, stddev_rating, city_values FROM summary WHERE stddev_rating >= 59;
